/**
 * 사람 목소리 — `VOICE-SCRIPT.md` §4.
 *
 * 브라우저 음성합성은 기계 소리라 어린이에게 친근하지 않으므로 런타임에서 사용하지 않는다.
 * 현재 실제 발화는 가이드 이벤트별 Juwonmom MP3이며, 아래 여덟 개는 이전 버전 호환·제작 기록이다.
 *
 * 아래 핵심 여덟 개의 호환 data URI를 갱신하는 방법은 이렇다.
 *
 *   1. mp3 여덟 개를 `public/voice/` 에 아래 파일 이름 그대로 둔다.
 *      ElevenLabs 웹 TTS의 MP3 128kbps 다운로드본을 그대로 쓸 수 있다
 *   2. `npm run voice` 를 돌린다. 이 파일이 data URI 로 다시 쓰인다
 *   3. `npm run verify` 로 정본과 MP3 서명·해독을 확인한다
 *
 * 오프라인 배포본은 `dist/voice/`에 전체 MP3를 복사한다. 파일이 없거나 재생에 실패해도
 * 브라우저 음성합성으로 바꾸지 않고 화면 글만 남긴다.
 */

export type VoiceId =
  | 'v-start'
  | 'v-crouch'
  | 'v-door'
  | 'v-close'
  | 'v-elevator'
  | 'v-success'
  | 'v-retry'
  | 'v-meeting';

export type VoiceGradeMode = 'easy' | 'normal';

/** 가이드 규칙 id와 이용 수준을 웹 MP3 파일명으로 바꾼다. */
export function guideVoiceFilename(ruleId: string, gradeMode: VoiceGradeMode): string {
  const slug = ruleId.replace(/[^A-Za-z0-9]+/g, '-').replace(/^-|-$/g, '').toLowerCase();
  return `guide-${slug}-${gradeMode}.mp3`;
}

/** 호환 보관용 핵심 대사 — 현재 게임에서는 가이드 이벤트 MP3가 같은 상황을 안내한다. */
export const VOICE_LINES: Record<VoiceId, string> = {
  'v-start': '불이 났어! 침착하게 밖으로 나가자.',
  'v-crouch': '연기가 오면 몸을 낮추고, 코와 입을 가리자.',
  'v-door': '문을 열기 전에 손등으로 손잡이를 살짝 만져 보자. 뜨거우면 열지 마.',
  'v-close': '지나온 문은 닫고 가자. 잠그지는 마.',
  'v-elevator': '엘리베이터는 타지 말고, 계단으로 가자.',
  'v-success': '무사히 나왔어! 정말 잘했어.',
  'v-retry': '괜찮아. 무엇이 어려웠는지 보고, 다시 해 보자.',
  'v-meeting': '밖으로 나온 뒤, 가족이 정한 만나는 곳으로 가자.',
};

/**
 * id → data URI. `npm run voice` 가 채운다.
 * 현재 런타임에서는 직접 호출하지 않는 호환 보관 자산이다.
 */
export const VOICE_CLIPS: Partial<Record<VoiceId, string>> = {
  'v-start': 'data:audio/mpeg;base64,',
  'v-crouch': 'data:audio/mpeg;base64,',
  'v-door': 'data:audio/mpeg;base64,',
  'v-close': 'data:audio/mpeg;base64,',
  'v-elevator': 'data:audio/mpeg;base64,',
  'v-success': 'data:audio/mpeg;base64,',
  'v-retry': 'data:audio/mpeg;base64,',
  'v-meeting': 'data:audio/mpeg;base64,',
};

export function hasVoiceClips(): boolean {
  return Object.keys(VOICE_CLIPS).length > 0;
}
